fn capitalize_first_letter(mut word: Vec<char>) -> Vec<char> {
    // If the first character is a lowercase ASCII letter, replace it with 'A'.
    if word[0].is_ascii_lowercase() {
        word[0] = 'A';
    }
    // Otherwise (it is already uppercase), we leave it unchanged.
    word
}

fn main() {
    let examples = vec![
        vec!['h', 'e', 'l', 'l', 'o'],
        vec!['A', 'b', 'c'],
        vec!['z', 'Z'],
        vec!['M', 'o', 'r', 'n', 'i', 'n', 'g'],
    ];

    for word in examples {
        let result = capitalize_first_letter(word.clone());
        println!("input: {:?} -> output: {:?}", word, result);
    }
}